// === Tab: mySketch ===
rotation_speed = 0;

function setup() {
  createCanvas(1000, 600);
  noStroke();
  background("#005");
  h = height / 2;
	w = width / 2;
}

function draw() {
  for (y = 0; y < h; y += 6) {
    c = lerpColor(color("#005"), color("#22489D"), y / h);
    fill(c);
    square(y, y, width - 2 * y);
  }
	push()
  fill("#28C752");
  for (i = 6000; i > 0; i--) {
    x = w + sin(i + rotation_speed) * sin(i * i ) * 250;
    y = h + 250 * cos(i * i);
    circle(x, y, 2);
  }
	pop()

	push()
  fill("#28C7BD");
  for (i = 4000; i > 0; i--) {
    x = w - sin(i + rotation_speed) * sin(i * i) * 200;
    y = h - 200 * cos(i * i);
    circle(x, y, 2);
  }
	pop()

	push()
  fill("#D25D69");
  for (i = 4000; i > 0; i--) {
    x = w + sin(i + rotation_speed) * sin(i * i) * 180;
    y = h + 180 * cos(i * i);
    circle(x, y, 2);
  }
	pop()

	push()
  fill("#D225E1");
  for (i = 4000; i > 0; i--) {
    x = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) + sin(i + rotation_speed) * sin(i * i) * 150 * noise(sin(i + rotation_speed) * sin(i * i) + i);
    y = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) + 150 * cos(i * i) * noise(cos(i * i) + i);
    circle(x, y, 2);
  }
	pop()

  rotation_speed += 0.01;
}

